// 砚边 · 听说多角色配音时间轴（Edge TTS 生成，本地音频，稳定可暂停/拖动）
window.YANBIAN_LISTEN_AUDIO={"l1":{"file":"audio/listen/l1.mp3","dur":44.014,"lines":[{"role":"Waitress","voice":"en-US-JennyNeural","start":0.0,"end":4.32,"text":"Good afternoon! What can I get for you today?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.67,"end":11.318,"text":"Hi, could I have a medium latte, please? And could you make it with oat milk?"},{"role":"Waitress","voice":"en-US-JennyNeural","start":11.668,"end":19.18,"text":"Of course. Anything to eat with that? Our cinnamon rolls are fresh out of the oven."},{"role":"Customer","voice":"en-US-AriaNeural","start":19.53,"end":26.202,"text":"Oh, they smell amazing. I'll take one. Could you heat it up?"},{"role":"Waitress","voice":"en-US-JennyNeural","start":26.552,"end":33.272,"text":"Sure thing. That'll be eight fifty. Can I get your name for the order?"},{"role":"Customer","voice":"en-US-AriaNeural","start":33.622,"end":38.014,"text":"It's Sarah. S-A-R-A-H."},{"role":"Waitress","voice":"en-US-JennyNeural","start":38.364,"end":43.86,"text":"Perfect, Sarah. It'll be ready in about five minutes."}]},"l2":{"file":"audio/listen/l2.mp3","dur":29.158,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":29.136,"text":"Attention, students. This is a reminder that the library will be closing early this Friday at five p.m. for annual maintenance. All books must be returned by Thursday evening. If you need to study late, the reading room in the Student Centre will remain open until eleven. Also, the writing workshop led by Professor Chen has been moved to Room 302. Thank you for your attention, and have a productive week."}]},"l3":{"file":"audio/listen/l3.mp3","dur":36.034,"lines":[{"role":"A","voice":"en-US-GuyNeural","start":0.0,"end":3.264,"text":"So, what are you up to this weekend?"},{"role":"B","voice":"en-US-JennyNeural","start":3.614,"end":10.79,"text":"Not much. Maybe I'll go for a hike if the weather holds. What about you?"},{"role":"A","voice":"en-US-GuyNeural","start":11.14,"end":18.22,"text":"I was thinking of catching a movie. They're showing that new thriller everyone's talking about."},{"role":"B","voice":"en-US-JennyNeural","start":18.57,"end":25.386,"text":"I heard it was a bit of a let-down, honestly. The review said the ending was predictable."},{"role":"A","voice":"en-US-GuyNeural","start":25.736,"end":32.456,"text":"Really? Well, in that case, maybe we could just grab coffee and catch up instead."},{"role":"B","voice":"en-US-JennyNeural","start":32.806,"end":35.902,"text":"That sounds like a much better plan."}]},"l4":{"file":"audio/listen/l4.mp3","dur":40.75,"lines":[{"role":"Agent","voice":"en-US-ChristopherNeural","start":0.0,"end":5.232,"text":"Good morning. May I see your passport and booking reference?"},{"role":"Traveler","voice":"en-US-JennyNeural","start":5.582,"end":11.15,"text":"Here you are. I'm flying to London on the nine forty-five."},{"role":"Agent","voice":"en-US-ChristopherNeural","start":11.5,"end":15.964,"text":"Thank you. Do you have any bags to check in?"},{"role":"Traveler","voice":"en-US-JennyNeural","start":16.314,"end":21.042,"text":"Just one suitcase. This is my carry-on."},{"role":"Agent","voice":"en-US-ChristopherNeural","start":21.392,"end":26.96,"text":"Please place the suitcase on the scale. It's a little over the limit."},{"role":"Traveler","voice":"en-US-JennyNeural","start":27.31,"end":32.854,"text":"Oh, sorry. I can move a few things into my backpack."},{"role":"Agent","voice":"en-US-ChristopherNeural","start":33.204,"end":40.596,"text":"That's fine. Here is your boarding pass. Boarding starts at gate B twelve."}]},"l5":{"file":"audio/listen/l5.mp3","dur":30.778,"lines":[{"role":"Landlord","voice":"en-US-EricNeural","start":0.0,"end":7.464,"text":"The apartment is available from the first of next month. It's two bedrooms, fully furnished."},{"role":"Student","voice":"en-US-AvaNeural","start":7.814,"end":11.222,"text":"What's the monthly rent, and what does it include?"},{"role":"Landlord","voice":"en-US-EricNeural","start":11.572,"end":17.86,"text":"It's eighteen hundred a month, including water and internet, but not electricity."},{"role":"Student","voice":"en-US-AvaNeural","start":18.21,"end":20.082,"text":"Do I need to pay a deposit?"},{"role":"Landlord","voice":"en-US-EricNeural","start":20.432,"end":26.432,"text":"Yes, one month's rent as a deposit, which is refundable if there's no damage."},{"role":"Student","voice":"en-US-AvaNeural","start":26.782,"end":30.646,"text":"That sounds reasonable. Could I see the contract first?"}]},"l6":{"file":"audio/listen/l6.mp3","dur":31.546,"lines":[{"role":"Interviewer","voice":"en-US-GuyNeural","start":0.0,"end":4.992,"text":"Thanks for coming in. Tell me a bit about yourself."},{"role":"Applicant","voice":"en-US-JennyNeural","start":5.342,"end":11.822,"text":"I'm a final-year student majoring in economics, and I interned at a marketing firm last summer."},{"role":"Interviewer","voice":"en-US-GuyNeural","start":12.172,"end":15.364,"text":"What interests you about this position?"},{"role":"Applicant","voice":"en-US-JennyNeural","start":15.714,"end":22.794,"text":"I've always been drawn to how data shapes business decisions, and your team's work in that area impresses me."},{"role":"Interviewer","voice":"en-US-GuyNeural","start":23.144,"end":26.336,"text":"When could you start if we make an offer?"},{"role":"Applicant","voice":"en-US-JennyNeural","start":26.686,"end":31.414,"text":"I can start immediately after graduation, in early July."}]},"l7":{"file":"audio/listen/l7.mp3","dur":31.438,"lines":[{"role":"Doctor","voice":"en-US-ChristopherNeural","start":0.0,"end":2.568,"text":"What seems to be the problem?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":2.918,"end":6.518,"text":"I've had a fever and a sore throat for about three days."},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":6.868,"end":9.964,"text":"Any cough or difficulty breathing?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":10.314,"end":13.122,"text":"A slight cough, but no trouble breathing."},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":13.472,"end":23.192,"text":"Let me check your temperature. It's slightly elevated. I'll prescribe some medicine; take it twice a day after meals."},{"role":"Patient","voice":"en-US-EmmaNeural","start":23.542,"end":26.806,"text":"Thank you. Should I stay home from school?"},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":27.156,"end":31.284,"text":"For a day or two, until the fever goes down."}]},"l8":{"file":"audio/listen/l8.mp3","dur":37.366,"lines":[{"role":"Clerk","voice":"en-US-GuyNeural","start":0.0,"end":4.128,"text":"Good afternoon. How can I help you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.478,"end":7.574,"text":"I'd like to open a savings account."},{"role":"Clerk","voice":"en-US-GuyNeural","start":7.924,"end":13.612,"text":"Certainly. Do you have your passport and proof of address with you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":13.962,"end":17.802,"text":"Here's my passport and a recent utility bill."},{"role":"Clerk","voice":"en-US-GuyNeural","start":18.152,"end":26.432,"text":"Great. There's a minimum balance of one hundred yuan. Would you like a debit card as well?"},{"role":"Customer","voice":"en-US-AriaNeural","start":26.782,"end":32.23,"text":"Yes, please. And can I manage the account online?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":32.58,"end":37.212,"text":"Absolutely. I'll help you set that up."}]},"l9":{"file":"audio/listen/l9.mp3","dur":26.578,"lines":[{"role":"Librarian","voice":"en-GB-SoniaNeural","start":0.0,"end":2.352,"text":"Can I help you find something?"},{"role":"Student","voice":"en-US-AvaNeural","start":2.702,"end":6.182,"text":"Yes, I'm looking for a book on modern architecture."},{"role":"Librarian","voice":"en-GB-SoniaNeural","start":6.532,"end":14.596,"text":"Let me check the catalogue. It's on the third floor, shelf B. I see you already have two books checked out."},{"role":"Student","voice":"en-US-AvaNeural","start":14.946,"end":17.754,"text":"They're due tomorrow. Can I renew them?"},{"role":"Librarian","voice":"en-GB-SoniaNeural","start":18.104,"end":24.224,"text":"You can renew once online, for another two weeks, as long as no one has requested them."},{"role":"Student","voice":"en-US-AvaNeural","start":24.574,"end":26.446,"text":"Perfect, thank you."}]},"l10":{"file":"audio/listen/l10.mp3","dur":32.65,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":5.16,"text":"Good evening, thank you for calling. How may I help you?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":5.51,"end":9.206,"text":"I'd like to reserve a table for four this Friday."},{"role":"Host","voice":"en-US-RogerNeural","start":9.556,"end":13.54,"text":"Certainly. What time would you prefer?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":13.89,"end":19.914,"text":"Around seven thirty, if possible. We're celebrating a birthday."},{"role":"Host","voice":"en-US-RogerNeural","start":20.264,"end":27.272,"text":"Let me see... we have a table by the window at seven thirty. Would that work?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":27.622,"end":32.518,"text":"That would be perfect. Could you hold it under the name Smith?"}]},"l11":{"file":"audio/listen/l11.mp3","dur":35.974,"lines":[{"role":"Clerk","voice":"en-US-GuyNeural","start":0.0,"end":4.368,"text":"Next, please. How can I help you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.718,"end":10.454,"text":"I'm here to collect a package. I got a notification this morning."},{"role":"Clerk","voice":"en-US-GuyNeural","start":10.804,"end":14.716,"text":"Do you have the tracking number and some form of ID?"},{"role":"Customer","voice":"en-US-AriaNeural","start":15.066,"end":19.578,"text":"Here's my phone with the tracking number, and my student card."},{"role":"Clerk","voice":"en-US-GuyNeural","start":19.928,"end":27.56,"text":"Let me scan this... It arrived this morning. Please sign here and I'll get it for you."},{"role":"Customer","voice":"en-US-AriaNeural","start":27.91,"end":32.854,"text":"Thank you. Does it need to be opened for inspection?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":33.204,"end":35.82,"text":"No, you're all set."}]},"l12":{"file":"audio/listen/l12.mp3","dur":29.95,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":3.672,"text":"Hi, are you interested in joining the gym?"},{"role":"Student","voice":"en-US-AvaNeural","start":4.022,"end":6.998,"text":"Maybe. What does a membership cost?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":7.348,"end":12.7,"text":"It's two hundred a month, or you can save by paying for six months upfront."},{"role":"Student","voice":"en-US-AvaNeural","start":13.05,"end":14.754,"text":"What equipment do you have?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":15.104,"end":22.448,"text":"We have free weights, and about twenty treadmills. There are also group classes in the evening."},{"role":"Student","voice":"en-US-AvaNeural","start":22.798,"end":25.15,"text":"Do I get a tour before deciding?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":25.5,"end":29.796,"text":"Of course. Let me show you around."}]},"l13":{"file":"audio/listen/l13.mp3","dur":36.082,"lines":[{"role":"Tourist","voice":"en-GB-ThomasNeural","start":0.0,"end":4.416,"text":"Excuse me, could you tell me how to get to the city museum?"},{"role":"Local","voice":"en-US-AnaNeural","start":4.766,"end":12.398,"text":"Sure. Go straight for about two blocks, then turn left at the traffic lights."},{"role":"Tourist","voice":"en-GB-ThomasNeural","start":12.748,"end":16.78,"text":"Two blocks and left. Is it far?"},{"role":"Local","voice":"en-US-AnaNeural","start":17.13,"end":26.538,"text":"No, it's about a ten-minute walk. You'll see a red brick building on your right. You can't miss it."},{"role":"Tourist","voice":"en-GB-ThomasNeural","start":26.888,"end":30.776,"text":"Great. Is there a bus I could take?"},{"role":"Local","voice":"en-US-AnaNeural","start":31.126,"end":35.95,"text":"You could, but honestly, walking is faster."}]},"l14":{"file":"audio/listen/l14.mp3","dur":34.33,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":3.936,"text":"Good morning, Bright Office, how may I help you?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":4.286,"end":8.246,"text":"Hello, could I speak to Mr. Davis, please?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":8.596,"end":14.02,"text":"I'm afraid he's in a meeting at the moment. Can I take a message?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":14.37,"end":23.178,"text":"Yes, please. This is Anna from the design team. Ask him to call me back about Tuesday's meeting."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":23.528,"end":27.536,"text":"Certainly. Does he have your number?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":27.886,"end":34.198,"text":"Yes, he does. Thank you. I'll wait to hear from him."}]},"l15":{"file":"audio/listen/l15.mp3","dur":40.03,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":14.688,"text":"Good evening, everyone. Tonight we're delighted to welcome Professor Helen Green from the Department of Environmental Science. Her research focuses on how cities can adapt to rising temperatures."},{"role":"Host","voice":"en-US-RogerNeural","start":15.038,"end":25.406,"text":"In her talk, she'll draw on case studies from three continents and explain why green roofs and urban trees matter more than we think."},{"role":"Host","voice":"en-US-RogerNeural","start":25.756,"end":39.964,"text":"The lecture will last about an hour, followed by a twenty-minute question-and-answer session. Please hold your questions until the end. Without further ado, let's welcome Professor Green."}]},"l16":{"file":"audio/listen/l16.mp3","dur":31.702,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":11.352,"text":"And now for the weather. Tomorrow morning will be cloudy with a chance of light rain in the north. Temperatures will peak at around twenty-two degrees in the afternoon."},{"role":"旁白","voice":"en-US-JennyNeural","start":11.702,"end":23.606,"text":"Over the weekend, a cold front will move in from the west, bringing stronger winds and a sharp drop in temperature. Saturday looks wet, but Sunday should clear up by midday."},{"role":"旁白","voice":"en-US-JennyNeural","start":23.956,"end":31.636,"text":"If you're planning any outdoor activities, Saturday is probably best avoided. That's all for now."}]},"l17":{"file":"audio/listen/l17.mp3","dur":35.062,"lines":[{"role":"Customer","voice":"en-US-AriaNeural","start":0.0,"end":5.736,"text":"Excuse me, I'd like to return this sweater. It doesn't fit."},{"role":"Clerk","voice":"en-US-GuyNeural","start":6.086,"end":8.822,"text":"Do you have the receipt with you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":9.172,"end":15.052,"text":"Yes, here it is. I bought it last week and I haven't worn it."},{"role":"Clerk","voice":"en-US-GuyNeural","start":15.402,"end":18.954,"text":"Would you prefer a refund or an exchange?"},{"role":"Customer","voice":"en-US-AriaNeural","start":19.304,"end":24.944,"text":"An exchange, please. Do you have this in a larger size?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":25.294,"end":32.566,"text":"Let me check the stock... Yes, we have one in medium. Here you are."},{"role":"Customer","voice":"en-US-AriaNeural","start":32.916,"end":34.908,"text":"Thanks a lot."}]},"l18":{"file":"audio/listen/l18.mp3","dur":40.054,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":6.0,"text":"Good afternoon, make yourself comfortable. How can we help you today?"},{"role":"Client","voice":"en-US-RogerNeural","start":6.35,"end":9.902,"text":"I'd like to book an appointment for a haircut."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":10.252,"end":14.452,"text":"Sure. What day were you thinking of?"},{"role":"Client","voice":"en-US-RogerNeural","start":14.802,"end":19.41,"text":"This Saturday, if possible, sometime in the morning."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":19.76,"end":29.096,"text":"Let me check... We have eleven or eleven thirty. I'd recommend the earlier slot; it's usually quieter."},{"role":"Client","voice":"en-US-RogerNeural","start":29.446,"end":35.518,"text":"Eleven works well. And could I ask for a trim rather than a full cut?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":35.868,"end":39.9,"text":"Of course. I'll note that down."}]},"l19":{"file":"audio/listen/l19.mp3","dur":32.842,"lines":[{"role":"President","voice":"en-US-GuyNeural","start":0.0,"end":4.152,"text":"Hi there, interested in joining the photography club?"},{"role":"Student","voice":"en-US-AvaNeural","start":4.502,"end":7.07,"text":"Maybe. What do you guys do?"},{"role":"President","voice":"en-US-GuyNeural","start":7.42,"end":17.788,"text":"We go on photo walks every other weekend, and once a term we hold an exhibition of members' work. You don't need a fancy camera; a phone is fine."},{"role":"Student","voice":"en-US-AvaNeural","start":18.138,"end":21.354,"text":"That sounds fun. Is there a membership fee?"},{"role":"President","voice":"en-US-GuyNeural","start":21.704,"end":31.112,"text":"Just fifty Yuan a year, which covers printing and exhibition costs. Our next meeting is on Thursday evening in Room 205."},{"role":"Student","voice":"en-US-AvaNeural","start":31.462,"end":32.71,"text":"Count me in."}]},"l20":{"file":"audio/listen/l20.mp3","dur":30.694,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":8.352,"text":"This is a traffic update. There has been an accident on the northbound lane of the ring road, near exit fifteen."},{"role":"旁白","voice":"en-US-JennyNeural","start":8.702,"end":18.95,"text":"One lane is currently blocked, and drivers should expect delays of up to twenty minutes. Traffic is being diverted onto the nearby side streets."},{"role":"旁白","voice":"en-US-JennyNeural","start":19.3,"end":30.628,"text":"The emergency services are on the scene, and we expect the road to reopen by six o'clock. Consider taking the underground if you're travelling through that area this evening."}]},"l21":{"file":"audio/listen/l21.mp3","dur":41.158,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":4.104,"text":"Welcome. Do you have a reservation?"},{"role":"Guest","voice":"en-GB-ThomasNeural","start":4.454,"end":8.726,"text":"Yes, a double room for two nights under the name Wang."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":9.076,"end":18.532,"text":"Let me check... Yes, a double room, non-smoking, for two nights. Could I see your ID, please?"},{"role":"Guest","voice":"en-GB-ThomasNeural","start":18.882,"end":23.49,"text":"Here you are. What time is breakfast served?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":23.84,"end":31.544,"text":"From seven to nine thirty in the restaurant on the ground floor. Check-out is at noon on your last day."},{"role":"Guest","voice":"en-GB-ThomasNeural","start":31.894,"end":36.142,"text":"Great. And is there Wi-Fi in the room?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":36.492,"end":41.004,"text":"Yes, the password is on the card in your key envelope."}]},"l22":{"file":"audio/listen/l22.mp3","dur":39.286,"lines":[{"role":"Waiter","voice":"en-GB-RyanNeural","start":0.0,"end":2.28,"text":"Are you ready to order?"},{"role":"Customer","voice":"en-US-AriaNeural","start":2.63,"end":8.174,"text":"Not quite. What would you recommend for a first-time visitor?"},{"role":"Waiter","voice":"en-GB-RyanNeural","start":8.524,"end":17.764,"text":"The mushroom risotto is our signature dish, and it's completely plant-based. The roasted cauliflower is also very popular."},{"role":"Customer","voice":"en-US-AriaNeural","start":18.114,"end":23.058,"text":"I'll have the risotto, please. Is it spicy?"},{"role":"Waiter","voice":"en-GB-RyanNeural","start":23.408,"end":28.184,"text":"Only mildly. Would you like a salad on the side?"},{"role":"Customer","voice":"en-US-AriaNeural","start":28.534,"end":34.774,"text":"Yes, a small one. And could I have still water rather than sparkling?"},{"role":"Waiter","voice":"en-GB-RyanNeural","start":35.124,"end":39.132,"text":"Certainly. I'll bring it right over."}]},"l23":{"file":"audio/listen/l23.mp3","dur":35.746,"lines":[{"role":"Tutor","voice":"en-US-EricNeural","start":0.0,"end":3.576,"text":"So, how is the essay coming along?"},{"role":"Student","voice":"en-US-AvaNeural","start":3.926,"end":8.366,"text":"I've written a first draft, but I'm not sure about the structure."},{"role":"Tutor","voice":"en-US-EricNeural","start":8.716,"end":18.412,"text":"That's a common issue. Try to make your main argument clear in the introduction, then use each body paragraph to support one point."},{"role":"Student","voice":"en-US-AvaNeural","start":18.762,"end":21.282,"text":"Should I include lots of quotations?"},{"role":"Tutor","voice":"en-US-EricNeural","start":21.632,"end":32.72,"text":"Only the ones you actually analyse. Quality matters more than quantity. Send me the draft by Friday and I'll give you detailed feedback."},{"role":"Student","voice":"en-US-AvaNeural","start":33.07,"end":35.614,"text":"Thanks, that's really helpful."}]},"l24":{"file":"audio/listen/l24.mp3","dur":55.054,"lines":[{"role":"Interviewer","voice":"en-US-GuyNeural","start":0.0,"end":7.536,"text":"Thank you for coming in today. Could you tell us a little about your experience with data analysis?"},{"role":"Applicant","voice":"en-US-JennyNeural","start":7.886,"end":16.502,"text":"Certainly. I worked on a sales dashboard at my previous company, and I used Excel and Python to clean the data."},{"role":"Interviewer","voice":"en-US-GuyNeural","start":16.852,"end":23.74,"text":"That sounds useful. How did you handle a situation where the data was incomplete?"},{"role":"Applicant","voice":"en-US-JennyNeural","start":24.09,"end":31.746,"text":"I checked the source with the Sales team and left a clear note in the report, so nobody treated missing values as zero."},{"role":"Interviewer","voice":"en-US-GuyNeural","start":32.096,"end":40.856,"text":"Good. This role also involves weekly presentations. Are you comfortable speaking to a large group?"},{"role":"Applicant","voice":"en-US-JennyNeural","start":41.206,"end":49.846,"text":"Yes. I presented to thirty colleagues every Monday, and I always prepared one slide with one clear message."},{"role":"Interviewer","voice":"en-US-GuyNeural","start":50.196,"end":54.9,"text":"Impressive. We will be in touch by Friday."}]},"l25":{"file":"audio/listen/l25.mp3","dur":31.03,"lines":[{"role":"Pharmacist","voice":"en-GB-SoniaNeural","start":0.0,"end":3.072,"text":"Good evening. How can I help you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":3.422,"end":9.47,"text":"I have a sore throat and a mild headache. Do you have anything I can take?"},{"role":"Pharmacist","voice":"en-GB-SoniaNeural","start":9.82,"end":12.772,"text":"Are you allergic to any medication?"},{"role":"Customer","voice":"en-US-AriaNeural","start":13.122,"end":15.498,"text":"Not that I know of."},{"role":"Pharmacist","voice":"en-GB-SoniaNeural","start":15.848,"end":21.656,"text":"Then this spray should help. Use it twice a day, and drink plenty of water."},{"role":"Customer","voice":"en-US-AriaNeural","start":22.006,"end":24.814,"text":"How long before I feel better?"},{"role":"Pharmacist","voice":"en-GB-SoniaNeural","start":25.164,"end":30.876,"text":"Usually two or three days. If the pain gets worse, see a doctor."}]},"l26":{"file":"audio/listen/l26.mp3","dur":39.07,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":4.848,"text":"Hello, Hillview Hotel. How may I help you?"},{"role":"Guest","voice":"en-US-JennyNeural","start":5.198,"end":10.214,"text":"I would like to book a double room for two nights, starting on the twelfth."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":10.564,"end":14.164,"text":"Do you need a quiet room away from the elevator?"},{"role":"Guest","voice":"en-US-JennyNeural","start":14.514,"end":19.578,"text":"Yes, that would be great. Is breakfast included?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":19.928,"end":26.6,"text":"Yes, it is served from seven to nine thirty. Could I have your name, please?"},{"role":"Guest","voice":"en-US-JennyNeural","start":26.95,"end":34.246,"text":"Sarah Miller. And could I check in late? My flight arrives around ten p.m."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":34.596,"end":38.916,"text":"Certainly. We will keep the room for you."}]},"l27":{"file":"audio/listen/l27.mp3","dur":31.774,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":31.752,"text":"Attention passengers. The train to Shanghai, scheduled to depart at eight fifteen, has been delayed by twenty minutes due to a signalling fault. We are sorry for the inconvenience. Passengers waiting for this service may use the lounge on the second floor, where hot drinks are available. Trains to Nanjing and Hangzhou are running on time. We will announce the new departure time as soon as we receive confirmation. Thank you for your patience."}]},"l28":{"file":"audio/listen/l28.mp3","dur":38.194,"lines":[{"role":"Student A","voice":"en-US-GuyNeural","start":0.0,"end":4.344,"text":"Have you finished the literature review for our group project?"},{"role":"Student B","voice":"en-US-JennyNeural","start":4.694,"end":11.918,"text":"Almost. I found six sources, but two of them are from websites rather than journals."},{"role":"Student A","voice":"en-US-GuyNeural","start":12.268,"end":18.7,"text":"We should use journal articles for the theory section. Could you look for two more?"},{"role":"Student B","voice":"en-US-JennyNeural","start":19.05,"end":25.626,"text":"Sure. I can do that tonight. What about the survey results?"},{"role":"Student A","voice":"en-US-GuyNeural","start":25.976,"end":32.24,"text":"I will put them into charts. We need to explain why the sample was small."},{"role":"Student B","voice":"en-US-JennyNeural","start":32.59,"end":38.062,"text":"Good idea. Let's meet on Thursday and put everything together."}]},"l29":{"file":"audio/listen/l29.mp3","dur":43.414,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":7.872,"text":"Today we are talking about sleep and memory. Dr. Lin, why is sleep important for learning?"},{"role":"Guest","voice":"en-US-JennyNeural","start":8.222,"end":14.966,"text":"During deep sleep, the brain replays what we learned during the day and strengthens the useful connections."},{"role":"Host","voice":"en-US-RogerNeural","start":15.316,"end":20.068,"text":"So pulling an all-nighter before an exam is not a good idea?"},{"role":"Guest","voice":"en-US-JennyNeural","start":20.418,"end":27.642,"text":"Exactly. Students who sleep after studying usually remember more than those who stay awake."},{"role":"Host","voice":"en-US-RogerNeural","start":27.992,"end":31.16,"text":"How many hours do adults need?"},{"role":"Guest","voice":"en-US-JennyNeural","start":31.51,"end":38.014,"text":"Most adults need seven to nine hours, and regular timing matters as much as duration."},{"role":"Host","voice":"en-US-RogerNeural","start":38.364,"end":43.26,"text":"That is a useful reminder. Thank you for joining us."}]},"l30":{"file":"audio/listen/l30.mp3","dur":35.206,"lines":[{"role":"Tenant","voice":"en-US-EmmaNeural","start":0.0,"end":4.608,"text":"Hello, Mr. Brown. This is Lisa from apartment 4B."},{"role":"Landlord","voice":"en-US-EricNeural","start":4.958,"end":9.47,"text":"Hi, Lisa. Is everything all right?"},{"role":"Tenant","voice":"en-US-EmmaNeural","start":9.82,"end":15.268,"text":"The shower has been leaking since Monday, and the bathroom floor is wet every morning."},{"role":"Landlord","voice":"en-US-EricNeural","start":15.618,"end":21.45,"text":"I am sorry to hear that. I will send a plumber tomorrow afternoon."},{"role":"Tenant","voice":"en-US-EmmaNeural","start":21.8,"end":26.096,"text":"Thank you. Will someone need to enter the apartment when I am out?"},{"role":"Landlord","voice":"en-US-EricNeural","start":26.446,"end":31.126,"text":"Only if you agree. I will text you first."},{"role":"Tenant","voice":"en-US-EmmaNeural","start":31.476,"end":35.052,"text":"That works for me. Thanks for being so quick."}]},"l31":{"file":"audio/listen/l31.mp3","dur":29.854,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":29.832,"text":"Welcome to the City Museum. You are now standing in the East Hall, where the collection of everyday objects from the nineteenth century is displayed. Look at the small wooden box in front of you. It was used by teachers to carry chalk and notebooks between classrooms. In the next room, you will find a collection of handwritten letters written by students who studied abroad. Please allow twenty minutes for this section, and mind the step at the entrance."}]},"l32":{"file":"audio/listen/l32.mp3","dur":36.238,"lines":[{"role":"Waiter","voice":"en-GB-RyanNeural","start":0.0,"end":3.96,"text":"Good evening. Are you ready to order?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.31,"end":8.726,"text":"Not quite. What is the soup of the day?"},{"role":"Waiter","voice":"en-GB-RyanNeural","start":9.076,"end":15.028,"text":"It is tomato and basil. Would you like a small bowl or a large one?"},{"role":"Customer","voice":"en-US-AriaNeural","start":15.378,"end":21.762,"text":"A small bowl, please. And I will have the grilled fish with vegetables."},{"role":"Waiter","voice":"en-GB-RyanNeural","start":22.112,"end":24.728,"text":"Would you like anything to drink?"},{"role":"Customer","voice":"en-US-AriaNeural","start":25.078,"end":31.126,"text":"Just water, thank you. Could you bring the bill when you bring the main course?"},{"role":"Waiter","voice":"en-GB-RyanNeural","start":31.476,"end":36.084,"text":"Of course. I will be back in a few minutes."}]},"l33":{"file":"audio/listen/l33.mp3","dur":43.534,"lines":[{"role":"Manager","voice":"en-US-GuyNeural","start":0.0,"end":7.176,"text":"Let's talk about your work this quarter. Overall, your report quality has improved a lot."},{"role":"Employee","voice":"en-US-AvaNeural","start":7.526,"end":12.134,"text":"Thank you. I have been checking my figures twice before sending them."},{"role":"Manager","voice":"en-US-GuyNeural","start":12.484,"end":21.052,"text":"That shows. One area to work on is meeting deadlines. Two reports were late in September."},{"role":"Employee","voice":"en-US-AvaNeural","start":21.402,"end":28.722,"text":"I see. The delay was caused by waiting for data from another team. I will ask earlier next time."},{"role":"Manager","voice":"en-US-GuyNeural","start":29.072,"end":33.392,"text":"Good. What support do you need from me?"},{"role":"Employee","voice":"en-US-AvaNeural","start":33.742,"end":38.158,"text":"Perhaps a short meeting at the start of each month to confirm priorities."},{"role":"Manager","voice":"en-US-GuyNeural","start":38.508,"end":43.38,"text":"That is reasonable. Let's try it in October."}]},"l34":{"file":"audio/listen/l34.mp3","dur":29.518,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":29.496,"text":"A new study released this week shows that urban trees can lower street temperatures by up to two degrees Celsius. Researchers compared satellite images with ground measurements in twelve cities and found that neighbourhoods with more shade had fewer heat-related emergency calls. The team recommends planting trees along busy roads and school playgrounds. City planners say the next step is to choose species that need little water and can survive hotter summers."}]},"l35":{"file":"audio/listen/l35.mp3","dur":36.91,"lines":[{"role":"Receptionist","voice":"en-US-AriaNeural","start":0.0,"end":5.184,"text":"Good morning, Bright Dental Clinic. How can I help you?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":5.534,"end":12.158,"text":"Hello. I have an appointment with Dr. Chen on Wednesday, but I have to reschedule."},{"role":"Receptionist","voice":"en-US-AriaNeural","start":12.508,"end":16.636,"text":"Certainly. What day would suit you?"},{"role":"Caller","voice":"en-US-MichelleNeural","start":16.986,"end":21.378,"text":"Could I come on Thursday afternoon, preferably after three?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":21.728,"end":26.912,"text":"Let me check. Thursday at three thirty is available."},{"role":"Caller","voice":"en-US-MichelleNeural","start":27.262,"end":31.99,"text":"That is perfect. Could you confirm the address again?"},{"role":"Receptionist","voice":"en-US-AriaNeural","start":32.34,"end":36.756,"text":"It is twenty-two King Street, opposite the post office."}]},"l36":{"file":"audio/listen/l36.mp3","dur":37.126,"lines":[{"role":"Librarian","voice":"en-GB-SoniaNeural","start":0.0,"end":3.216,"text":"Hello. How can I help you today?"},{"role":"Student","voice":"en-US-AvaNeural","start":3.566,"end":8.75,"text":"I am looking for articles about online learning, but I am not sure where to start."},{"role":"Librarian","voice":"en-GB-SoniaNeural","start":9.1,"end":13.732,"text":"Have you tried the academic database on the library website?"},{"role":"Student","voice":"en-US-AvaNeural","start":14.082,"end":19.146,"text":"Yes, but I got too many results. How can I narrow them down?"},{"role":"Librarian","voice":"en-GB-SoniaNeural","start":19.496,"end":28.76,"text":"Try limiting the search to peer-reviewed journals published after 2020. You can also choose the subject education technology."},{"role":"Student","voice":"en-US-AvaNeural","start":29.11,"end":33.19,"text":"That is helpful. Can I borrow the books on the second shelf?"},{"role":"Librarian","voice":"en-GB-SoniaNeural","start":33.54,"end":36.972,"text":"Yes, but they are due back in seven days."}]},"l37":{"file":"audio/listen/l37.mp3","dur":31.222,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":31.2,"text":"Welcome to Maple University. During the next four years, three places will become familiar to you: the library, the language lab, and the student centre. The library is open until midnight during exam weeks. The language lab requires a booking, which you can make through the campus app. The student centre runs a writing clinic every Tuesday and a career workshop on the first Friday of each month. Please keep your student card with you at all times."}]},"l38":{"file":"audio/listen/l38.mp3","dur":31.846,"lines":[{"role":"Dentist","voice":"en-US-ChristopherNeural","start":0.0,"end":4.872,"text":"Please sit back. When did you last see a dentist?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":5.222,"end":7.43,"text":"About two years ago, I think."},{"role":"Dentist","voice":"en-US-ChristopherNeural","start":7.78,"end":11.5,"text":"Do you feel any pain when you drink something cold?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":11.85,"end":14.514,"text":"Only in this tooth, on the left side."},{"role":"Dentist","voice":"en-US-ChristopherNeural","start":14.864,"end":22.712,"text":"I can see a small cavity. We can fill it today. It will take about thirty minutes."},{"role":"Patient","voice":"en-US-EmmaNeural","start":23.062,"end":24.358,"text":"Will it hurt?"},{"role":"Dentist","voice":"en-US-ChristopherNeural","start":24.708,"end":31.692,"text":"You will feel pressure, but the area will be numb. Please raise your hand if you need a break."}]},"l39":{"file":"audio/listen/l39.mp3","dur":34.486,"lines":[{"role":"Tutor","voice":"en-US-EricNeural","start":0.0,"end":3.264,"text":"How is your presentation coming along?"},{"role":"Student","voice":"en-US-AvaNeural","start":3.614,"end":8.102,"text":"I have ten slides, but my tutor said the topic is too broad."},{"role":"Tutor","voice":"en-US-EricNeural","start":8.452,"end":10.948,"text":"What is your main argument?"},{"role":"Student","voice":"en-US-AvaNeural","start":11.298,"end":16.41,"text":"That social media affects students' attention, but the evidence is mixed."},{"role":"Tutor","voice":"en-US-EricNeural","start":16.76,"end":23.552,"text":"Then make that your question. Cut the history section and keep three strong studies."},{"role":"Student","voice":"en-US-AvaNeural","start":23.902,"end":26.35,"text":"Should I include a survey of my own?"},{"role":"Tutor","voice":"en-US-EricNeural","start":26.7,"end":34.332,"text":"Only if you can explain the sample clearly. Remember, ten minutes means about eight slides."}]},"l40":{"file":"audio/listen/l40.mp3","dur":45.25,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":5.784,"text":"Why do people check their phones so often, even when they are with friends?"},{"role":"Guest","voice":"en-US-JennyNeural","start":6.134,"end":14.294,"text":"Because each notification gives a small reward. The brain learns to expect it, so checking becomes a habit."},{"role":"Host","voice":"en-US-RogerNeural","start":14.644,"end":18.196,"text":"Does that mean we should delete social media?"},{"role":"Guest","voice":"en-US-JennyNeural","start":18.546,"end":27.21,"text":"Not necessarily. A better approach is to turn off non-essential notifications and set fixed times for checking."},{"role":"Host","voice":"en-US-RogerNeural","start":27.56,"end":30.416,"text":"What about the fear of missing out?"},{"role":"Guest","voice":"en-US-JennyNeural","start":30.766,"end":38.542,"text":"That feeling usually passes in a few minutes. You can train yourself to wait before reaching for the phone."},{"role":"Host","voice":"en-US-RogerNeural","start":38.892,"end":42.804,"text":"So the goal is awareness, not perfection."},{"role":"Guest","voice":"en-US-JennyNeural","start":43.154,"end":45.074,"text":"Exactly."}]},"l41":{"file":"audio/listen/l41.mp3","dur":39.13,"lines":[{"role":"Customer","voice":"en-US-AriaNeural","start":0.0,"end":3.312,"text":"Hi, is this bike still available?"},{"role":"Owner","voice":"en-US-EricNeural","start":3.662,"end":11.03,"text":"Yes, it is. It is three years old, but I replaced the tyres last spring."},{"role":"Customer","voice":"en-US-AriaNeural","start":11.38,"end":13.828,"text":"How much are you asking?"},{"role":"Owner","voice":"en-US-EricNeural","start":14.178,"end":19.938,"text":"Four hundred and twenty yuan. I can include the lock and the helmet."},{"role":"Customer","voice":"en-US-AriaNeural","start":20.288,"end":23.288,"text":"Would you take three hundred and fifty?"},{"role":"Owner","voice":"en-US-EricNeural","start":23.638,"end":27.67,"text":"I could do three hundred and eighty if you pay in cash."},{"role":"Customer","voice":"en-US-AriaNeural","start":28.02,"end":32.004,"text":"Deal. Could I test it first?"},{"role":"Owner","voice":"en-US-EricNeural","start":32.354,"end":38.954,"text":"Sure. The brake on the right is a little tight, but otherwise it rides well."}]},"l42":{"file":"audio/listen/l42.mp3","dur":37.282,"lines":[{"role":"Officer","voice":"en-US-GuyNeural","start":0.0,"end":3.672,"text":"Please place your laptop and your belt in the tray."},{"role":"Traveler","voice":"en-US-JennyNeural","start":4.022,"end":6.902,"text":"Do I need to take off my shoes?"},{"role":"Officer","voice":"en-US-GuyNeural","start":7.252,"end":12.82,"text":"No, not today. Put your bag on the belt, please."},{"role":"Traveler","voice":"en-US-JennyNeural","start":13.17,"end":17.514,"text":"I have a bottle of water. Is that allowed?"},{"role":"Officer","voice":"en-US-GuyNeural","start":17.864,"end":23.408,"text":"I am afraid not. You can empty it at the sink over there."},{"role":"Traveler","voice":"en-US-JennyNeural","start":23.758,"end":28.582,"text":"All right. What about this small bottle of perfume?"},{"role":"Officer","voice":"en-US-GuyNeural","start":28.932,"end":33.084,"text":"If it is under one hundred millilitres, it is fine."},{"role":"Traveler","voice":"en-US-JennyNeural","start":33.434,"end":37.106,"text":"It is fifty. Thank you."}]},"l43":{"file":"audio/listen/l43.mp3","dur":32.734,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":32.712,"text":"Artificial intelligence systems learn patterns from large amounts of data. In language tasks, a model predicts the next word based on what it has seen before. This makes the output feel natural, but it does not mean the system understands the world in the way people do. Researchers therefore ask two questions: how accurate is the answer, and how can we check it? For students, the practical rule is simple: use these tools to draft and to question, not to replace your own judgement."}]},"l44":{"file":"audio/listen/l44.mp3","dur":38.662,"lines":[{"role":"Clerk","voice":"en-US-GuyNeural","start":0.0,"end":4.32,"text":"Good morning. Do you have a reservation?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.67,"end":9.398,"text":"Yes, I booked a small car for three days under the name Wang."},{"role":"Clerk","voice":"en-US-GuyNeural","start":9.748,"end":16.396,"text":"Let me check. I have you down for a compact car with automatic transmission."},{"role":"Customer","voice":"en-US-AriaNeural","start":16.746,"end":21.258,"text":"That is right. Is insurance included?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":21.608,"end":28.28,"text":"Basic insurance is included. You can add full cover for fifty yuan a day."},{"role":"Customer","voice":"en-US-AriaNeural","start":28.63,"end":33.862,"text":"I will take the basic one. What time should I return it?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":34.212,"end":38.508,"text":"By five p.m. on Friday, with a full tank of petrol."}]},"l45":{"file":"audio/listen/l45.mp3","dur":42.046,"lines":[{"role":"Manager","voice":"en-US-GuyNeural","start":0.0,"end":7.176,"text":"We would like to offer you the position. The starting salary is eight thousand yuan a month."},{"role":"Applicant","voice":"en-US-JennyNeural","start":7.526,"end":14.774,"text":"Thank you. I am excited about the role. Could you tell me about the review schedule?"},{"role":"Manager","voice":"en-US-GuyNeural","start":15.124,"end":19.444,"text":"Salaries are reviewed once a year, usually in March."},{"role":"Applicant","voice":"en-US-JennyNeural","start":19.794,"end":25.338,"text":"I see. Would it be possible to have a six-month review instead?"},{"role":"Manager","voice":"en-US-GuyNeural","start":25.688,"end":29.648,"text":"That is unusual, but I can ask the HR team."},{"role":"Applicant","voice":"en-US-JennyNeural","start":29.998,"end":33.67,"text":"I would also like to confirm the training budget."},{"role":"Manager","voice":"en-US-GuyNeural","start":34.02,"end":41.892,"text":"There is an annual allowance of two thousand yuan for courses. I will send the full offer by email."}]},"l46":{"file":"audio/listen/l46.mp3","dur":39.862,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":7.176,"text":"Welcome back. Today we are discussing a novel about a young teacher in a small town."},{"role":"Guest","voice":"en-US-JennyNeural","start":7.526,"end":12.278,"text":"What struck me was the way she kept a notebook of small kindnesses."},{"role":"Host","voice":"en-US-RogerNeural","start":12.628,"end":18.34,"text":"I noticed that too. It changes how she sees her students."},{"role":"Guest","voice":"en-US-JennyNeural","start":18.69,"end":23.514,"text":"Some readers found the ending too quiet, but I thought it was honest."},{"role":"Host","voice":"en-US-RogerNeural","start":23.864,"end":27.392,"text":"Do you think the author wanted us to feel hopeful?"},{"role":"Guest","voice":"en-US-JennyNeural","start":27.742,"end":35.878,"text":"Yes, but not in an easy way. The last page says change begins with attention, not with a speech."},{"role":"Host","voice":"en-US-RogerNeural","start":36.228,"end":39.708,"text":"That line alone is worth the whole book."}]},"l47":{"file":"audio/listen/l47.mp3","dur":30.718,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":30.696,"text":"This is an urgent weather update. Heavy rain is expected between four and eight this evening. The city has issued a yellow warning, and public buses on the riverside route will be suspended after six. Residents are advised to avoid underpasses and to keep away from tall trees. Schools will dismiss students thirty minutes early. The meteorological office says the rain should stop by midnight, and normal service will resume tomorrow morning."}]},"l48":{"file":"audio/listen/l48.mp3","dur":40.27,"lines":[{"role":"Clerk","voice":"en-US-GuyNeural","start":0.0,"end":4.368,"text":"Next, please. How can I help you?"},{"role":"Customer","voice":"en-US-AriaNeural","start":4.718,"end":10.406,"text":"I would like to send this package to Chengdu. How long will it take?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":10.756,"end":18.244,"text":"By standard post, three to five days. Express is faster, but it costs twice as much."},{"role":"Customer","voice":"en-US-AriaNeural","start":18.594,"end":23.85,"text":"Standard is fine. Does the price include insurance?"},{"role":"Clerk","voice":"en-US-GuyNeural","start":24.2,"end":30.464,"text":"It includes basic cover up to fifty yuan. Would you like to add more?"},{"role":"Customer","voice":"en-US-AriaNeural","start":30.814,"end":35.878,"text":"No, thank you. The contents are only books."},{"role":"Clerk","voice":"en-US-GuyNeural","start":36.228,"end":40.116,"text":"Please fill in this form with the address and phone number."}]},"l49":{"file":"audio/listen/l49.mp3","dur":44.602,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":5.448,"text":"Today's question: should cities invest more in solar power?"},{"role":"Guest A","voice":"en-US-JennyNeural","start":5.798,"end":14.222,"text":"Yes. The cost of panels has fallen sharply, and a roof can generate electricity for twenty years."},{"role":"Guest B","voice":"en-US-GuyNeural","start":14.572,"end":22.804,"text":"I agree about the cost, but solar is weak on cloudy days. Cities still need a stable base supply."},{"role":"Guest A","voice":"en-US-JennyNeural","start":23.154,"end":29.754,"text":"That is why batteries matter. A small battery can store power for evening use."},{"role":"Guest B","voice":"en-US-GuyNeural","start":30.104,"end":38.24,"text":"Batteries are expensive, though. I would put the money into wind first, where our coast has a clear advantage."},{"role":"Host","voice":"en-US-RogerNeural","start":38.59,"end":44.47,"text":"So both of you want cleaner energy, but you disagree about where to start."}]},"l50":{"file":"audio/listen/l50.mp3","dur":36.478,"lines":[{"role":"Counsellor","voice":"en-GB-SoniaNeural","start":0.0,"end":5.76,"text":"You mentioned that you feel stressed before exams. What happens in your body?"},{"role":"Student","voice":"en-US-AvaNeural","start":6.11,"end":10.358,"text":"My heart beats fast, and I cannot sleep the night before."},{"role":"Counsellor","voice":"en-GB-SoniaNeural","start":10.708,"end":18.652,"text":"Let's try something simple. Before bed, write down three things you need to do tomorrow, then close the notebook."},{"role":"Student","voice":"en-US-AvaNeural","start":19.002,"end":20.61,"text":"Will that really help?"},{"role":"Counsellor","voice":"en-GB-SoniaNeural","start":20.96,"end":29.0,"text":"It tells your brain that the plan is safe to leave until morning. Many students sleep better after doing it for a week."},{"role":"Student","voice":"en-US-AvaNeural","start":29.35,"end":31.174,"text":"I can try that tonight."},{"role":"Counsellor","voice":"en-GB-SoniaNeural","start":31.524,"end":36.324,"text":"And remember, feeling nervous is not the same as being unprepared."}]},"l51":{"file":"audio/listen/l51.mp3","dur":36.154,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":7.8,"text":"Our guest today grew up in Chengdu and now studies in London. What food do you miss most?"},{"role":"Guest","voice":"en-US-JennyNeural","start":8.15,"end":14.75,"text":"Hotpot, honestly. But I have learned to cook it with ingredients I can find here."},{"role":"Host","voice":"en-US-RogerNeural","start":15.1,"end":17.356,"text":"Do your friends like it?"},{"role":"Guest","voice":"en-US-JennyNeural","start":17.706,"end":23.49,"text":"At first they found the pepper too strong. Now they ask for extra."},{"role":"Host","voice":"en-US-RogerNeural","start":23.84,"end":27.128,"text":"What surprised you about British food?"},{"role":"Guest","voice":"en-US-JennyNeural","start":27.478,"end":36.022,"text":"The variety of cheese, and the fact that a Sunday roast takes hours. Cooking is a way to understand a place."}]},"l52":{"file":"audio/listen/l52.mp3","dur":41.314,"lines":[{"role":"A","voice":"en-US-GuyNeural","start":0.0,"end":4.704,"text":"Can you hear me? The connection was breaking up."},{"role":"B","voice":"en-US-JennyNeural","start":5.054,"end":9.47,"text":"I can hear you now. You are moving a little."},{"role":"A","voice":"en-US-GuyNeural","start":9.82,"end":15.652,"text":"Sorry, I am walking to the library. Is your exam tomorrow?"},{"role":"B","voice":"en-US-JennyNeural","start":16.002,"end":21.354,"text":"Yes, in the morning. I have been revising since seven."},{"role":"A","voice":"en-US-GuyNeural","start":21.704,"end":24.344,"text":"Have you taken a break today?"},{"role":"B","voice":"en-US-JennyNeural","start":24.694,"end":29.71,"text":"Only for lunch. I keep forgetting to drink water."},{"role":"A","voice":"en-US-GuyNeural","start":30.06,"end":36.324,"text":"Promise me you will stop at ten tonight. Sleep will help you remember more."},{"role":"B","voice":"en-US-JennyNeural","start":36.674,"end":41.138,"text":"All right. I will see you after the exam."}]},"l53":{"file":"audio/listen/l53.mp3","dur":35.926,"lines":[{"role":"Doctor","voice":"en-US-ChristopherNeural","start":0.0,"end":4.2,"text":"Good morning. What seems to be the problem?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":4.55,"end":8.582,"text":"I have had a cough for almost two weeks, and it gets worse at night."},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":8.932,"end":12.1,"text":"Any fever or difficulty breathing?"},{"role":"Patient","voice":"en-US-EmmaNeural","start":12.45,"end":15.258,"text":"No fever. I feel tired, though."},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":15.608,"end":25.208,"text":"Let me listen to your chest. Take a deep breath. It sounds clear. I think it is post-viral."},{"role":"Patient","voice":"en-US-EmmaNeural","start":25.558,"end":27.19,"text":"Do I need medicine?"},{"role":"Doctor","voice":"en-US-ChristopherNeural","start":27.54,"end":35.772,"text":"Not really. Rest and warm drinks are enough. Come back if the cough lasts another week."}]},"l54":{"file":"audio/listen/l54.mp3","dur":36.502,"lines":[{"role":"Tourist","voice":"en-GB-ThomasNeural","start":0.0,"end":4.32,"text":"Excuse me, is this the right bus for the railway station?"},{"role":"Local","voice":"en-US-AnaNeural","start":4.67,"end":12.686,"text":"No, this one goes to the museum. You need the number twelve from the stop across the road."},{"role":"Tourist","voice":"en-GB-ThomasNeural","start":13.036,"end":15.436,"text":"How often does it come?"},{"role":"Local","voice":"en-US-AnaNeural","start":15.786,"end":23.37,"text":"About every ten minutes. It takes twenty minutes, and you want the fifth stop."},{"role":"Tourist","voice":"en-GB-ThomasNeural","start":23.72,"end":26.696,"text":"Could you tell me the name of that stop?"},{"role":"Local","voice":"en-US-AnaNeural","start":27.046,"end":32.158,"text":"Green Square. Ask the driver to let you know."},{"role":"Tourist","voice":"en-GB-ThomasNeural","start":32.508,"end":36.348,"text":"Thank you. That is very clear."}]},"l55":{"file":"audio/listen/l55.mp3","dur":36.574,"lines":[{"role":"Chair","voice":"en-US-RogerNeural","start":0.0,"end":7.896,"text":"Let's begin. Three items today: the budget, the launch date, and the website."},{"role":"Colleague","voice":"en-US-AvaNeural","start":8.246,"end":12.35,"text":"On the budget, we have ten percent left for advertising."},{"role":"Chair","voice":"en-US-RogerNeural","start":12.7,"end":16.42,"text":"Good. What about the launch date?"},{"role":"Colleague","voice":"en-US-AvaNeural","start":16.77,"end":21.258,"text":"The design team needs one more week, so I suggest the fifteenth."},{"role":"Chair","voice":"en-US-RogerNeural","start":21.608,"end":27.08,"text":"Does everyone agree? Then we will move the launch to the fifteenth."},{"role":"Colleague","voice":"en-US-AvaNeural","start":27.43,"end":31.654,"text":"For the website, we still need someone to check the mobile version."},{"role":"Chair","voice":"en-US-RogerNeural","start":32.004,"end":36.42,"text":"I will ask the technical team to handle it this afternoon."}]},"l56":{"file":"audio/listen/l56.mp3","dur":32.398,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":32.376,"text":"A research team has successfully tested a small lunar rover this week. The rover, which weighs about thirty kilograms, travelled two kilometres over rough ground in a simulated environment. Its cameras sent images back to a control room in Beijing, where engineers checked the data in real time. The next test will focus on the rover's ability to charge its battery using solar power during a long lunar night. If all goes well, the design could support future missions."}]},"l57":{"file":"audio/listen/l57.mp3","dur":46.882,"lines":[{"role":"Host","voice":"en-US-RogerNeural","start":0.0,"end":6.576,"text":"Many students reread their notes for hours. Is that the best way to remember?"},{"role":"Guest","voice":"en-US-JennyNeural","start":6.926,"end":13.478,"text":"Not really. Rereading feels productive, but testing yourself works better."},{"role":"Host","voice":"en-US-RogerNeural","start":13.828,"end":18.076,"text":"So close the book and answer questions from memory?"},{"role":"Guest","voice":"en-US-JennyNeural","start":18.426,"end":25.098,"text":"Yes. Try to explain a concept without looking, then check what you missed."},{"role":"Host","voice":"en-US-RogerNeural","start":25.448,"end":28.136,"text":"How often should you review?"},{"role":"Guest","voice":"en-US-JennyNeural","start":28.486,"end":35.446,"text":"Review once after one day, then after a week. This is called spaced repetition."},{"role":"Host","voice":"en-US-RogerNeural","start":35.796,"end":40.188,"text":"It sounds simple, but most students skip it."},{"role":"Guest","voice":"en-US-JennyNeural","start":40.538,"end":46.706,"text":"Because it feels harder. That difficulty is exactly what makes it work."}]},"l58":{"file":"audio/listen/l58.mp3","dur":37.126,"lines":[{"role":"Coordinator","voice":"en-US-JennyNeural","start":0.0,"end":5.064,"text":"Welcome. Your job today is at the information desk."},{"role":"Volunteer","voice":"en-US-GuyNeural","start":5.414,"end":8.03,"text":"What should I tell visitors?"},{"role":"Coordinator","voice":"en-US-JennyNeural","start":8.38,"end":17.092,"text":"Give them the map, and point out the two entrances. If someone asks about the talk, check the schedule before answering."},{"role":"Volunteer","voice":"en-US-GuyNeural","start":17.442,"end":20.394,"text":"What if I do not know the answer?"},{"role":"Coordinator","voice":"en-US-JennyNeural","start":20.744,"end":26.816,"text":"Write the question down and send a message to the office. Never guess."},{"role":"Volunteer","voice":"en-US-GuyNeural","start":27.166,"end":29.518,"text":"How long is the shift?"},{"role":"Coordinator","voice":"en-US-JennyNeural","start":29.868,"end":36.972,"text":"Three hours, with a fifteen-minute break. You can have lunch after the next group arrives."}]},"l59":{"file":"audio/listen/l59.mp3","dur":38.674,"lines":[{"role":"Driver","voice":"en-US-EricNeural","start":0.0,"end":1.656,"text":"Where to?"},{"role":"Passenger","voice":"en-US-AriaNeural","start":2.006,"end":6.638,"text":"The training centre on Rose Street, near the city library."},{"role":"Driver","voice":"en-US-EricNeural","start":6.988,"end":13.012,"text":"Is that the one on the north side? The traffic there is heavy at this hour."},{"role":"Passenger","voice":"en-US-AriaNeural","start":13.362,"end":17.97,"text":"Yes. Could we take the ring road instead?"},{"role":"Driver","voice":"en-US-EricNeural","start":18.32,"end":23.696,"text":"It is a little longer, but faster. Do you need a receipt?"},{"role":"Passenger","voice":"en-US-AriaNeural","start":24.046,"end":28.678,"text":"Yes, please. I can pay by card."},{"role":"Driver","voice":"en-US-EricNeural","start":29.028,"end":33.9,"text":"No problem. It should take about twenty minutes."},{"role":"Passenger","voice":"en-US-AriaNeural","start":34.25,"end":38.498,"text":"Thank you. I have a meeting at four."}]},"l60":{"file":"audio/listen/l60.mp3","dur":33.574,"lines":[{"role":"旁白","voice":"en-US-JennyNeural","start":0.0,"end":33.552,"text":"Four years ago, you arrived with questions. Today you leave with better ones. Along the way, you learned more than the content of your courses. You learned how to disagree politely, how to start again after a failed experiment, and how to ask for help. The world will not always reward the fastest answer. It will reward the person who listens carefully and keeps learning. Wherever you go next, take your curiosity with you. Congratulations, graduates."}]}};
